cd /hutian/pr && git pull -q origin dev 2>&1|tail -1; git fetch -q origin document; git show origin/document:dev/built-from|head -1; git log --oneline|head -1; git show origin/document:dev/document.pdf > /tmp/dev.pdf; pdfinfo /tmp/dev.pdf | grep Pages; grep -c "^@" paper/references.bib; python3 - <<'EOF'
import pymupdf,re
d=pymupdf.open("/tmp/dev.pdf")
for i,p in enumerate(d):
    t=p.get_text()
    for k in ("References","Impact Statement","AI Disclosure","Appendix"):
        if re.search(r"^"+k,t,re.M): print(i+1,k)
EOF
pdffonts /tmp/dev.pdf | awk 'NR>2{print $2,$3}' | sort | uniq -c; ls -la /tmp/dev.pdf | awk '{print $5}'
